package com.camjewell.treasurechesthelper;

import java.awt.Color;
import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum ChestTier
{
	BEGINNER("Beginner", "Oak", new Color(0xB8B8B8)),
	EASY("Easy", "Oak", new Color(0x4CBB17)),
	MEDIUM("Medium", "Teak", new Color(0x3FA9F5)),
	HARD("Hard", "Mahogany", new Color(0xB563EB)),
	ELITE("Elite", "Mahogany", new Color(0xF2C511)),
	MASTER("Master", "Mahogany", new Color(0xE74C3C));

	private final String displayName;
	// Lowest treasure chest that can store this tier
	private final String minimumChest;
	private final Color color;
}

package com.camjewell.treasurechesthelper;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "Treasure Chest Helper",
	description = "Shows which POH treasure chest tier a Treasure Trails reward is stored in when hovering it inside your house",
	tags = {"poh", "house", "costume", "treasure", "chest", "clue", "stash", "construction"}
)
public class TreasureChestHelperPlugin extends Plugin
{
	private static final String ITEMS_RESOURCE = "chest_items.tsv";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private TreasureChestTooltipOverlay overlay;

	private Map<Integer, ChestTier> itemTiers = Collections.emptyMap();

	// Every player-owned house has exactly one exit portal, so its presence in the scene means we're in a house.
	@Getter
	private boolean inHouse;

	@Override
	protected void startUp() throws Exception
	{
		itemTiers = loadItemTiers();
		overlayManager.add(overlay);
		clientThread.invoke(this::scanSceneForPortal);
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		itemTiers = Collections.emptyMap();
		inHouse = false;
	}

	ChestTier getTier(int itemId)
	{
		return itemTiers.get(itemId);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		// Spawn events for the new scene arrive after LOADING, so clear here and let them set it again
		if (event.getGameState() == GameState.LOADING || event.getGameState() == GameState.LOGIN_SCREEN)
		{
			inHouse = false;
		}
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		if (event.getGameObject().getId() == ObjectID.POH_EXIT_PORTAL)
		{
			inHouse = true;
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		if (event.getGameObject().getId() == ObjectID.POH_EXIT_PORTAL)
		{
			inHouse = false;
		}
	}

	// One-off scan for when the plugin is enabled while already standing in a house
	private void scanSceneForPortal()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		Scene scene = client.getTopLevelWorldView().getScene();
		for (Tile[][] plane : scene.getTiles())
		{
			for (Tile[] row : plane)
			{
				for (Tile tile : row)
				{
					if (tile == null)
					{
						continue;
					}

					for (GameObject object : tile.getGameObjects())
					{
						if (object != null && object.getId() == ObjectID.POH_EXIT_PORTAL)
						{
							inHouse = true;
							return;
						}
					}
				}
			}
		}
	}

	private Map<Integer, ChestTier> loadItemTiers() throws IOException
	{
		Map<Integer, ChestTier> tiers = new HashMap<>();
		try (InputStream in = TreasureChestHelperPlugin.class.getResourceAsStream(ITEMS_RESOURCE))
		{
			if (in == null)
			{
				throw new IOException("Missing resource " + ITEMS_RESOURCE);
			}

			BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8));
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#"))
				{
					continue;
				}

				// TIER<TAB>itemId<TAB>name
				String[] parts = line.split("\t");
				tiers.put(Integer.parseInt(parts[1]), ChestTier.valueOf(parts[0]));
			}
		}

		log.debug("Loaded {} treasure chest items", tiers.size());
		return tiers;
	}
}

package com.camjewell.treasurechesthelper;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.MenuEntry;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetUtil;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;
import net.runelite.client.util.ColorUtil;

class TreasureChestTooltipOverlay extends Overlay
{
	private final Client client;
	private final TreasureChestHelperPlugin plugin;
	private final TooltipManager tooltipManager;
	private final ItemManager itemManager;

	@Inject
	TreasureChestTooltipOverlay(Client client, TreasureChestHelperPlugin plugin, TooltipManager tooltipManager, ItemManager itemManager)
	{
		this.client = client;
		this.plugin = plugin;
		this.tooltipManager = tooltipManager;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (client.isMenuOpen())
		{
			return null;
		}

		MenuEntry[] menuEntries = client.getMenu().getMenuEntries();
		if (menuEntries.length == 0)
		{
			return null;
		}

		// The last entry is the one under the cursor (the left-click option)
		MenuEntry entry = menuEntries[menuEntries.length - 1];
		Widget widget = entry.getWidget();
		if (widget == null || !(plugin.isInHouse() || isBankWidget(widget)))
		{
			return null;
		}

		int itemId = getItemId(widget);
		if (itemId <= 0)
		{
			return null;
		}

		// Resolves bank placeholders (and notes) to the real item
		ChestTier tier = plugin.getTier(itemManager.canonicalize(itemId));
		if (tier == null)
		{
			return null;
		}

		tooltipManager.add(new Tooltip("Treasure chest: "
			+ ColorUtil.wrapWithColorTag(tier.getDisplayName(), tier.getColor())
			+ " (" + tier.getMinimumChest() + "+)"));
		return null;
	}

	// There's no bank in a house, so the bank and its inventory panel are allowed anywhere
	private static boolean isBankWidget(Widget widget)
	{
		int interfaceId = WidgetUtil.componentToInterface(widget.getId());
		return interfaceId == InterfaceID.BANKMAIN || interfaceId == InterfaceID.BANKSIDE;
	}

	private static int getItemId(Widget widget)
	{
		if (widget.getItemId() > 0)
		{
			return widget.getItemId();
		}

		// Equipment slots hold the item in a child widget
		Widget child = widget.getChild(1);
		return child != null ? child.getItemId() : -1;
	}
}

package com.camjewell.treasurechesthelper;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TreasureChestHelperPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TreasureChestHelperPlugin.class);
		RuneLite.main(args);
	}
}
